/// Aspen installs DPoS code only when enabled and empty. At Cornus,
/// DPoS is replaced when enabled, and every OP account is replaced.
/// DPoS updates precede OP updates. Distinct OP addresses are sorted:
/// their independent SetCode operations commute for final state only;
/// this does not claim equality of arbitrary callback/event order.
pub fn code_updates(
    period: u64,
    aspen_one: u64,
    cornus: u64,
    dpos_present: bool,
    dpos_code_empty: bool,
) -> Vec<NativeCodeUpdate> {
    let mut updates = Vec::new();
    if dpos_present {
        if period >= aspen_one && dpos_code_empty {
            updates.push(NativeCodeUpdate {
                address: DPOS_ADDRESS,
                code: ASPEN_DPOS_CODE,
            });
        }
        if period == cornus {
            updates.push(NativeCodeUpdate {
                address: DPOS_ADDRESS,
                code: CORNUS_DPOS_CODE,
            });
        }
    }
    if period == cornus {
        updates.extend_from_slice(OP_UPDATES);
    }
    updates
}

