    #[test]
    fn aspen_only_installs_into_enabled_empty_dpos() {
        assert!(code_updates(9, 10, 20, true, true).is_empty());
        assert!(code_updates(10, 10, 20, false, true).is_empty());
        assert!(code_updates(10, 10, 20, true, false).is_empty());
        assert_eq!(
            code_updates(10, 10, 20, true, true),
            vec![NativeCodeUpdate {
                address: DPOS_ADDRESS,
                code: ASPEN_DPOS_CODE
            }]
        );
        assert_eq!(
            code_updates(21, 10, 20, true, true)[0].code,
            ASPEN_DPOS_CODE
        );
    }
    #[test]
    fn cornus_replaces_enabled_dpos_then_all_independent_op_accounts() {
        let disabled = code_updates(20, 10, 20, false, true);
        assert_eq!(disabled, OP_UPDATES);
        assert!(
            disabled
                .windows(2)
                .all(|pair| pair[0].address < pair[1].address)
        );
        assert!(
            disabled
                .iter()
                .all(|update| update.address != DPOS_ADDRESS && !update.code.is_empty())
        );
        let present = code_updates(20, 10, 20, true, false);
        assert_eq!(
            present[0],
            NativeCodeUpdate {
                address: DPOS_ADDRESS,
                code: CORNUS_DPOS_CODE
            }
        );
        assert_eq!(&present[1..], OP_UPDATES);
        assert!(code_updates(19, 10, 20, false, true).is_empty());
        assert!(code_updates(21, 10, 20, false, true).is_empty());
    }
    #[test]
    fn empty_dpos_at_cornus_preserves_both_ordered_go_assignments() {
        let updates = code_updates(20, 10, 20, true, true);
        assert_eq!(updates[0].code, ASPEN_DPOS_CODE);
        assert_eq!(updates[1].code, CORNUS_DPOS_CODE);
        assert_eq!(&updates[2..], OP_UPDATES);
        let before_aspen = code_updates(20, 30, 20, true, true);
        assert_eq!(before_aspen[0].code, CORNUS_DPOS_CODE);
        assert_eq!(&before_aspen[1..], OP_UPDATES);
    }
